package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type DateRec struct {
	DtId   string
	DtYyyy int64
	DtMm   int64
	DtDd   int64
}

var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var dateRec DateRec
var dateFile *os.File
var scanner *bufio.Scanner

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func storePic(val int64, digits int) int64 {
	mod := pow10(digits)
	v := val % mod
	if v < 0 {
		v += mod
	}
	return v
}

func formatPic9(val int64, digits int) string {
	mod := pow10(digits)
	v := val % mod
	if v < 0 {
		v += mod
	}
	return fmt.Sprintf("%0*d", digits, v)
}

func parseNum(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	// keep only digits and optional sign
	t2 := strings.TrimSpace(t)
	if t2 == "" {
		return 0
	}
	// s may contain spaces inside, remove them
	t2 = strings.ReplaceAll(t2, " ", "")
	if t2 == "" {
		return 0
	}
	n, err := strconv.ParseInt(t2, 10, 64)
	if err != nil {
		// try to extract digits
		var digits strings.Builder
		for _, ch := range t2 {
			if ch >= '0' && ch <= '9' {
				digits.WriteRune(ch)
			}
		}
		if digits.Len() == 0 {
			return 0
		}
		n, _ = strconv.ParseInt(digits.String(), 10, 64)
	}
	return n
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func MainPara() {
	var err error
	dateFile, err = os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty
		dateFile = nil
		scanner = bufio.NewScanner(strings.NewReader(""))
	} else {
		scanner = bufio.NewScanner(dateFile)
		// allow long lines
		const maxCapacity = 1024 * 1024
		buf := make([]byte, maxCapacity)
		scanner.Buffer(buf, maxCapacity)
	}
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if dateFile != nil {
		dateFile.Close()
	}
	fmt.Printf("VALID: %s BAD MONTH: %s BAD DAY: %s\n", formatPic9(WsValid, 2), formatPic9(WsBadMonth, 2), formatPic9(WsBadDay, 2))
}

func ReadPara() {
	if scanner != nil && scanner.Scan() {
		line := scanner.Text()
		if len(line) < 12 {
			line = line + strings.Repeat(" ", 12-len(line))
		} else if len(line) > 12 {
			line = line[:12]
		}
		dateRec.DtId = line[0:4]
		dateRec.DtYyyy = parseNum(line[4:8])
		dateRec.DtMm = parseNum(line[8:10])
		dateRec.DtDd = parseNum(line[10:12])
		// truncate stored file fields to picture size (low-order digits)
		dateRec.DtYyyy = storePic(dateRec.DtYyyy, 4)
		dateRec.DtMm = storePic(dateRec.DtMm, 2)
		dateRec.DtDd = storePic(dateRec.DtDd, 2)
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	LeapPara()
	if dateRec.DtMm < 1 || dateRec.DtMm > 12 {
		WsBadMonth = storePic(WsBadMonth+1, 2)
		fmt.Printf("%s BAD MONTH %s\n", dateRec.DtId, formatPic9(dateRec.DtMm, 2))
	} else {
		DaysPara()
		if dateRec.DtDd < 1 || dateRec.DtDd > WsMaxDay {
			WsBadDay = storePic(WsBadDay+1, 2)
			fmt.Printf("%s BAD DAY %s MAX %s\n", dateRec.DtId, formatPic9(dateRec.DtDd, 2), formatPic9(WsMaxDay, 2))
		} else {
			WsValid = storePic(WsValid+1, 2)
			fmt.Printf("%s VALID %s-%s-%s\n", dateRec.DtId, formatPic9(dateRec.DtYyyy, 4), formatPic9(dateRec.DtMm, 2), formatPic9(dateRec.DtDd, 2))
		}
	}
	ReadPara()
}

func LeapPara() {
	WsQ = storePic(dateRec.DtYyyy/4, 4)
	WsR4 = storePic(dateRec.DtYyyy%4, 3)
	WsQ = storePic(dateRec.DtYyyy/100, 4)
	WsR100 = storePic(dateRec.DtYyyy%100, 3)
	WsQ = storePic(dateRec.DtYyyy/400, 4)
	WsR400 = storePic(dateRec.DtYyyy%400, 3)
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DaysPara() {
	switch dateRec.DtMm {
	case 2:
		if WsLeapFlag == "Y" {
			WsMaxDay = storePic(29, 2)
		} else {
			WsMaxDay = storePic(28, 2)
		}
	case 4, 6, 9, 11:
		WsMaxDay = storePic(30, 2)
	default:
		WsMaxDay = storePic(31, 2)
	}
}

func main() {
	MainPara()
}
